package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class DivisibilityRulesTest {
 private static int independentWitness(int n,int d){if(d!=3)return n%10;return String.valueOf(n).chars().map(c->c-'0').sum();}
 private void checkPublic(Question q){var v=DivisibilityRules.read(q);assertNotNull(v);int expected=independentWitness(v.number(),v.divisor());boolean divides=v.number()%v.divisor()==0;q.answers=new String[]{"poison"};q.expression="poison";Checker c=new Checker();assertTrue(c.check(q,List.of(),List.of(""+expected,divides?"1":"0")).correct());assertEquals(0,c.check(q,List.of(),List.of(""+(expected+1),divides?"1":"0")).index);assertEquals(1,c.check(q,List.of(),List.of(""+expected,divides?"0":"1")).index);assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("","")).status);assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of(""+expected,"yes")).status);assertTrue(q.choices.isEmpty());assertEquals(v.relation().equals("factor")?"약수이다":"배수이다",DivisibilityRules.options(q).get("1"));}
 @Test public void publicRulesZeroUpperBoundAndBothDirections(){
  for(int n:new int[]{0,1,2,3,5,10,15,999999,1000000})for(int d:new int[]{2,3,5})for(String relation:List.of("factor","multiple"))checkPublic(DivisibilityRules.make(n,d,relation));
  assertEquals(54,DivisibilityRules.ruleValue(new DivisibilityRules.Givens(999999,3,"factor")));assertFalse(DivisibilityRules.verdict(new DivisibilityRules.Givens(1000000,3,"multiple")));
  for(int d:new int[]{2,3,5})assertTrue(DivisibilityRules.verdict(new DivisibilityRules.Givens(0,d,"factor")));
  for(int bad:new int[]{-1,1000001})try{DivisibilityRules.make(bad,2,"factor");fail();}catch(IllegalArgumentException expected){}
  for(int bad:new int[]{0,1,4,6})try{DivisibilityRules.make(10,bad,"factor");fail();}catch(IllegalArgumentException expected){}
  Question q=DivisibilityRules.make(12,3,"factor");q.prompt=q.prompt.replace("3은 12의 약수인가요?","12는 3의 약수인가요?");assertNull(DivisibilityRules.read(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("3","1")).status);
 }
 @Test public void blankHelpRequiresOriginalRuleValueAndRelation(){
  for(int d:new int[]{2,3,5})for(String relation:List.of("factor","multiple")){
   Question q=DivisibilityRules.make(999999,d,relation);q.answers=new String[]{"poison"};q.expression="poison";DivisibilityRules.attach(q);HelpPlan help=HelpPlan.forQuestion(q);assertEquals(3,help.size());assertFalse(help.canTransfer());assertTrue(help.restore(null,q.id).entries.stream().allMatch(String::isEmpty));assertTrue(help.step(0).accepts("999999"));assertTrue(help.step(1).accepts(""+independentWitness(999999,d)));assertTrue(help.step(2).accepts(999999%d==0?"1":"0"));assertFalse(help.step(2).accepts(999999%d==0?"0":"1"));assertEquals(d==3?"각 자리 숫자의 합 = ":"일의 자리 숫자 = ",help.step(1).before);
  }
 }
 @Test public void entireSmallDomainUsesEveryPublicConditionBeforeOldest(){
  for(int max:new int[]{1,2,3}){
   CurriculumLimits limits=new CurriculumLimits("wholeMaximum="+max+";minGiven=0;maxGiven="+max+";maxResult=54;nonnegative=true");Set<String> independent=new HashSet<>();for(int n=0;n<=max;n++)for(int d:new int[]{2,3,5})for(String relation:List.of("factor","multiple"))independent.add(DivisibilityRules.make(n,d,relation).signature());assertEquals(6*(max+1),independent.size());assertEquals(independent.size(),DivisibilityRules.count(max));
   Set<String> indexed=new HashSet<>();for(int i=0;i<DivisibilityRules.count(max);i++){Question q=DivisibilityRules.indexed(i,max);assertTrue(limits.allows(q));assertTrue(indexed.add(q.signature()));}assertEquals(independent,indexed);
   Map<String,Integer> recent=new LinkedHashMap<>();Random pinned=new Random(){@Override public int nextInt(int bound){return 0;}};while(recent.size()<independent.size()){Question q=DivisibilityRules.next(pinned,limits,recent);assertTrue(limits.allows(q));assertFalse(recent.containsKey(q.signature()));recent.put(q.signature(),recent.size());}assertEquals(independent,recent.keySet());String oldest=recent.keySet().iterator().next();assertEquals(oldest,DivisibilityRules.next(pinned,limits,recent).signature());recent.put(oldest,recent.size());assertEquals(1,(int)recent.get(DivisibilityRules.next(pinned,limits,recent).signature()));
  }
  assertEquals(6,DivisibilityRules.count(0));assertEquals(6000006,DivisibilityRules.count(1000000));assertNotNull(DivisibilityRules.read(DivisibilityRules.indexed(6000005,1000000)));for(int i:new int[]{-1,6000006})try{DivisibilityRules.indexed(i,1000000);fail();}catch(IllegalArgumentException expected){}
 }
 @Test public void normalGradeAndBoundsKeepDivisorSeparateFromInputRange(){
  Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"NA");GlobalCurriculum.choosePack(p,"na-nied-primary-2024-v1");var pack=GlobalCurriculum.pack(p);assertTrue(pack.inGrade(DivisibilityRules.ID,7));assertFalse(pack.inGrade(DivisibilityRules.ID,6));assertFalse(Curriculum.inCurriculum(Catalog.get(DivisibilityRules.ID),2022));CurriculumLimits limits=GlobalCurriculum.limits(pack.id,DivisibilityRules.ID,7);Generator g=new Generator(new Random(338));List<String>recent=new ArrayList<>();Set<Integer>divisors=new HashSet<>();Set<String>relations=new HashSet<>();boolean yes=false,no=false;
  for(int i=0;i<100;i++){Question q=g.next(DivisibilityRules.ID,recent,true,limits);assertTrue(limits.allows(q));assertFalse(recent.contains(q.signature()));recent.add(q.signature());var v=DivisibilityRules.read(q);divisors.add(v.divisor());relations.add(v.relation());yes|=DivisibilityRules.verdict(v);no|=!DivisibilityRules.verdict(v);checkPublic(q);}
  assertEquals(3,divisors.size());assertEquals(2,relations.size());assertTrue(yes&&no);checkPublic(g.create(Catalog.get(DivisibilityRules.ID)));
  CurriculumLimits small=new CurriculumLimits("wholeMaximum=1;minGiven=1;maxGiven=1;maxResult=54;nonnegative=true");assertTrue(small.allows(DivisibilityRules.make(1,5,"factor")));assertFalse(small.allows(DivisibilityRules.make(0,5,"factor")));assertFalse(small.allows(DivisibilityRules.make(2,2,"factor")));Map<String,Integer> recentSmall=new LinkedHashMap<>();Random pinned=new Random(){@Override public int nextInt(int bound){return 0;}};for(int i=0;i<6;i++){Question q=DivisibilityRules.next(pinned,small,recentSmall);assertEquals(1,DivisibilityRules.read(q).number());assertFalse(recentSmall.containsKey(q.signature()));recentSmall.put(q.signature(),i);}assertEquals(0,(int)recentSmall.get(DivisibilityRules.next(pinned,small,recentSmall).signature()));
  Map<String,Integer> zeroRecent=new LinkedHashMap<>();for(int i=0;i<6;i++){Question q=IndexedQuestionSupply.choose(DivisibilityRules.count(0),index->DivisibilityRules.indexed(index,0),pinned,CurriculumLimits.NONE,zeroRecent);assertEquals(0,DivisibilityRules.read(q).number());assertFalse(zeroRecent.containsKey(q.signature()));zeroRecent.put(q.signature(),i);}assertEquals(0,(int)zeroRecent.get(IndexedQuestionSupply.choose(DivisibilityRules.count(0),index->DivisibilityRules.indexed(index,0),pinned,CurriculumLimits.NONE,zeroRecent).signature()));
 }
}
